:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  min-height: 100%;
  background: #0f1117;
}

body {
  font-family: Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

* {
  box-sizing: border-box;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0f1117;
  color: #f4f7fb;
}

.card {
  width: 100%;
  max-width: 560px;
  background: #171b24;
  border: 1px solid #2d3443;
  border-radius: 8px;
  padding: 20px;
  display: grid;
  gap: 16px;
  box-shadow: 0 18px 48px rgba(0,0,0,.28);
}

.heading {
  display: grid;
  gap: 6px;
}

.eyebrow {
  margin: 0;
  color: #9fb0c7;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
}

.title {
  margin: 0;
  font-size: 22px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: 0;
}

.intro {
  margin: 0;
  color: #c7d2e1;
  font-size: 14px;
  line-height: 1.5;
}

.label {
  display: block;
  font-size: 13px;
  color: #c7d2e1;
  margin-bottom: 6px;
  font-weight: 700;
}

.combo {
  position: relative;
}

.input {
  width: 100%;
  min-height: 44px;
  padding: 11px 12px;
  border-radius: 8px;
  border: 1px solid #3d4657;
  background: #10141d;
  color: #f4f7fb;
  outline: none;
  font-size: 15px;
}

.input::placeholder {
  color: #7f8ba0;
}

.input:focus {
  border-color: #6ee7b7;
  box-shadow: 0 0 0 3px rgba(110,231,183,.16);
}

.list {
  position: absolute;
  z-index: 10;
  left: 0;
  right: 0;
  margin: 8px 0 0;
  padding: 6px;
  max-height: 250px;
  overflow: auto;
  border-radius: 8px;
  border: 1px solid #2d3443;
  background: #10141d;
  box-shadow: 0 18px 36px rgba(0,0,0,.36);
  list-style: none;
}

.option,.status {
  min-height: 38px;
  display: flex;
  align-items: center;
  padding: 9px 10px;
  border-radius: 6px;
  font-size: 14px;
  line-height: 1.35;
}

.option {
  cursor: pointer;
  color: #f4f7fb;
}

.option:hover,.option.active {
  background: #243044;
}

.option[aria-selected="true"] {
  outline: 1px solid rgba(110,231,183,.55);
}

.status {
  color: #9fb0c7;
}

.status--error {
  color: #fecaca;
}

.hint {
  margin: 0;
  color: #9fb0c7;
  font-size: 12px;
  line-height: 1.45;
}

mark {
  background: rgba(110,231,183,.25);
  color: #f4f7fb;
  border-radius: 3px;
  padding: 0 2px;
}
